INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('88774bd4-9ef7-4f64-ba69-94ddf246e62c', '650e8400-e29b-41d4-a716-446655440001', 'How Long Should a Power Bank Actually Last', 'how-long-should-a-power-bank-actually-last', 'A 20,000mAh power bank does not give a 3,000mAh phone battery 6.6 full charges. Voltage conversion losses mean the real number is closer to four, and every manufacturer knows this and prints the bigger number anyway.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('bb5ebf7c-af31-4018-88a3-c8de52ba66b5', '650e8400-e29b-41d4-a716-446655440001', 'Five Desk Accessories Worth the Drawer Space', 'five-desk-accessories-worth-the-drawer-space', 'We sell a lot of desk accessories, and we''re honest about the fact that most desk accessories are clutter with a UPC code. So this list is short on purpose — five things we''d actually replace if ours broke tomorrow.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('8e91acd6-0467-413c-8395-858b18cac0a8', '650e8400-e29b-41d4-a716-446655440001', 'Why We Tune Aviator Flat, Not Bassy', 'why-we-tune-aviator-flat', 'Walk into any electronics store, put on a random pair of headphones, and play something with a kick drum. The pair that sounds "best" in that five-second test is almost always the one with an artificially boosted low end. It sounds impressive for a demo and fatiguing for a workday.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('39d1224f-c65f-4768-a8fe-4edc2afff691', '650e8400-e29b-41d4-a716-446655440002', 'Why We Only Use Soy Wax', 'why-we-only-use-soy-wax', 'Soy wax burns at a lower, more even temperature than paraffin, which means a longer burn time from the same size jar and a cleaner burn with less soot buildup on the glass.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('97dc1e77-117b-44da-bb63-bc6a47699821', '650e8400-e29b-41d4-a716-446655440002', 'Caring for Handmade Ceramics (So They Actually Last)', 'caring-for-handmade-ceramics', 'Everything we sell is fired to cone 6, which means it''s fully vitrified and safe for a dishwasher and microwave. That said, hand washing extends the life of a hand-painted glaze, especially anything with metallic or crackle finishes.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('d4d65083-5a77-4b0f-a26d-fafd4a2ea0cf', '650e8400-e29b-41d4-a716-446655440002', 'A Day in the Studio: How a Hearth Mug Gets Made', 'a-day-in-the-studio-hearth-mug', 'Priya throws mugs on Tuesdays and Thursdays, twenty to twenty-five a session, each one shaped by hand on the wheel in about four minutes once the clay is centered. What looks fast is actually the easy part.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('cbbcbb3b-8a4f-4be6-9784-900e553e0a04', '650e8400-e29b-41d4-a716-446655440003', 'Recovery Isn''t Optional', 'recovery-isnt-optional', 'Foam rolling before a workout increases range of motion without the strength loss that static stretching can cause pre-lift. After a workout, it''s about circulation and breaking up the stiffness that turns into next-day soreness.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('220cec55-d694-4e57-93f1-82ddc88819e3', '650e8400-e29b-41d4-a716-446655440003', 'Kettlebell Basics: Three Moves Worth Mastering', 'kettlebell-basics-three-moves', 'The kettlebell swing trains hip hinge power better than almost anything else in a home gym, and it does it in a movement pattern that transfers directly to picking things up off the floor for the rest of your life.
INSERT INTO public.blog_posts (id, store_id, title, slug, content, excerpt, featured_image_url, meta_title, meta_description, status, published_at, scheduled_for, tags, category, view_count, created_at, updated_at) VALUES ('e62e52ad-513f-4e1a-a06f-f312fcfe901e', '650e8400-e29b-41d4-a716-446655440003', 'Building a Home Gym in 30 Square Feet', 'building-a-home-gym-in-30-square-feet', 'The equipment that gets used is the equipment you don''t have to set up. An adjustable dumbbell pair and a kettlebell cover most strength work without a rack. A yoga mat and a foam roller cover the rest.
